def transform(grid):
    """Mark the background boundary just beyond the lone marker, away from guide 2."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Locate the full guide and the non-background marker on its side.
    hr = next((r for r in range(h) if all(v == 2 for v in g[r])), None)
    if hr is not None:
        bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
        points = [(r,c) for r in range(h) for c in range(w) if g[r][c] not in (bg,2)]
        if points:
            # Paint the row immediately farther from the guide than the marker cluster.
            r = min(x[0] for x in points) - 1 if max(x[0] for x in points) < hr else max(x[0] for x in points) + 1
            if 0 <= r < h:
                for c in range(w):
                    if g[r][c] == bg:
                        g[r][c] = 8
            return g
        vc = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
        if vc is not None:
            return g
    return g

if __name__ == '__main__':
